<template>
  <AppHeader />
  <main class="audio-lab" data-route-motion-root>
    <header class="lab-heading">
      <div><p class="lab-eyebrow">AURORA / AUDIO STUDIO</p><h1>{{ state.tab==='speakers'?'让声音，走出一台设备。':'把一首歌，重新摆进空间。' }}</h1><p>连接身边的音响，或者重新摆放一首歌里的每个声音。</p></div>
      <button class="lab-quiet" @click="router.push({name:'profile'})"><AppIcon name="arrow-left" :size="16" /> 音乐库</button>
    </header>
    <nav class="lab-tabs" aria-label="音频实验室">
      <button :class="{'is-active':state.tab==='speakers'}" :aria-pressed="state.tab==='speakers'" @click="setTab('speakers')"><span aria-hidden="true">◧</span><strong>多设备同步音响</strong><small>让多台设备，一起发声</small></button>
      <button :class="{'is-active':state.tab==='spatial'}" :aria-pressed="state.tab==='spatial'" @click="setTab('spatial')"><span aria-hidden="true"><AppIcon name="audio-lines" :size="16" /></span><strong>空间混音台</strong><small>用普通耳机，听见声场</small></button>
    </nav>
    <p v-if="state.notice" class="lab-notice" role="status">{{ state.notice }}<button aria-label="关闭提示" @click="state.notice=''"><AppIcon name="x" :size="16" /></button></p>
    <div v-if="state.error" class="lab-error" role="alert"><span>{{ state.error }}</span><button v-if="state.tab==='speakers'" @click="reconnect()">重新连接</button><button aria-label="关闭错误提示" @click="state.error=''"><AppIcon name="x" :size="16" /></button></div>

    <MaintenanceFeature v-if="state.tab==='speakers'" target="feature.speakerGroup">
      <section v-if="!user.isLoggedIn" class="lab-guest"><span aria-hidden="true">◧</span><h2>把身边的设备连接起来</h2><p>登录同一个网易云账号，在每台设备打开音频实验室，即可加入同一播放组。</p><button class="lab-primary" @click="openLoginDialog()">登录并连接设备</button><small>空间混音台也支持直接导入本地音频。</small></section>
      <div v-else class="lab-speakers">
        <section class="lab-card lab-room">
          <header class="lab-card-heading"><div><p class="lab-eyebrow">ONE TRACK, MANY SPEAKERS</p><h2>{{ state.room?.name || '你的播放组' }}</h2></div><span class="lab-status" :class="{'is-online':state.connected}">{{ state.connecting?'连接中':state.connected?'实时连接':'未连接' }}</span></header>
          <template v-if="!state.room">
            <div class="lab-room-empty"><div class="lab-device-art" aria-hidden="true"><i/><i/><i/></div><h3>从这一台开始</h3><p>创建播放组，再用其他设备登录同一账号加入。<br/>每台设备都需要点击一次“加入并启用”。</p><button class="lab-primary" :disabled="Boolean(state.groupBusy) || state.connecting" @click="createRoom()">{{ state.groupBusy==='create'?'创建中…':'创建播放组' }}</button></div>
          </template>
          <template v-else>
            <div class="lab-current-source">
              <div class="lab-source-mark" :class="{'is-playing':state.room.playing && state.enabled}" aria-hidden="true"><i v-for="i in 7" :key="i" :style="{'--i':i}" /></div>
              <p class="lab-eyebrow">当前同步音源</p><h3>{{ state.room.source?.name || '选择一份音源，让设备准备好' }}</h3>
              <p v-if="countdown>0" class="lab-countdown">{{ countdown }} 秒后同步开始</p>
              <p v-else>{{ state.room.members.filter(m=>m.ready).length }} / {{ state.room.members.length }} 台设备已准备好</p>
            </div>
            <div class="lab-transport">
              <button v-if="!joined || !state.enabled || state.contextState!=='running'" class="lab-primary" :disabled="Boolean(state.groupBusy)" @click="joinRoom()">{{ joined?'启用本机音响':'加入并启用' }}</button>
              <template v-else><span class="lab-enabled"><i/>本机音响已启用</span><button class="lab-quiet" @click="leaveRoom()">退出播放组</button></template>
              <button v-if="isHost" class="lab-primary" :disabled="Boolean(state.groupBusy)||!state.room.source || (!state.room.playing && state.room.members.some(m=>!m.ready))" @click="command(state.room.playing?'PAUSE':'PLAY')">{{ state.room.playing?'暂停全部':'同步播放' }}</button>
            </div>
            <div v-if="state.room.source" class="lab-timeline"><input aria-label="播放组进度" type="range" min="0" :max="state.room.source.durationMs" :value="groupPosition" :disabled="!isHost || Boolean(state.groupBusy)" @change="command('SEEK',{positionMs:Number($event.target.value)})"/><span>{{ time(groupPosition/1000) }}</span><span>{{ time(state.room.source.durationMs/1000) }}</span></div>
            <p v-if="state.sourceBusy" class="lab-muted" role="status">正在下载并校验统一音源，随后准备本机音响…</p>
            <p v-if="state.sourceError" class="lab-error" role="alert">{{ state.sourceError }}<button @click="retrySource()">重新准备</button></p>
            <div class="lab-room-meta"><span>{{ isHost?'本机正在主持':'由主持设备控制播放' }}</span><button v-if="isHost" class="lab-link" :disabled="Boolean(state.groupBusy)" @click="command('CLOSE')">结束播放组</button></div>
            <section class="lab-device-list" aria-label="播放组设备">
              <article v-for="member in state.room.members" :key="member.deviceId" class="lab-device">
                <header><span class="lab-device-icon" aria-hidden="true">{{ member.clientType==='DESKTOP'?'▣':'▥' }}</span><div><strong>{{ member.name }} <small>{{ member.deviceId.slice(0,4) }}</small></strong><p>{{ member.deviceId===api.deviceId?'本机 · ':'' }}{{ member.deviceId===state.room.hostDeviceId?'主持 · ':'' }}{{ member.ready?'音响就绪':'等待启用或准备音源' }}</p></div><i :class="{'is-ready':member.ready}" /></header>
                <div class="lab-device-output">
                  <label><span>音量</span><input type="range" min="0" max="1" step=".01" :value="member.volume" :disabled="!canAdjust(member)" @input="previewOutput(member.deviceId,{volume:Number($event.target.value)})" @change="saveOutput(member.deviceId)" /></label>
                  <label><span>声道</span><select :value="member.channel" :disabled="!canAdjust(member)" @change="previewOutput(member.deviceId,{channel:$event.target.value});saveOutput(member.deviceId)"><option value="STEREO">立体声</option><option value="LEFT">左声道</option><option value="RIGHT">右声道</option></select></label>
                  <label><span>延迟补偿 / ms</span><input type="number" min="-1000" max="1000" step="1" :value="member.delayMs" :disabled="!canAdjust(member)" @change="previewOutput(member.deviceId,{delayMs:Math.round(Math.max(-1000,Math.min(1000,Number($event.target.value)||0)))});saveOutput(member.deviceId)" /></label>
                </div>
                <footer><span>对时估计 ±{{ Math.round(member.clockUncertaintyMs) }} ms</span><span v-if="member.driftMs!==null">调度偏差 {{ Math.round(member.driftMs) }} ms</span><button v-if="isHost && member.deviceId!==api.deviceId" class="lab-link" :disabled="Boolean(state.groupBusy)" @click="command('TRANSFER',{deviceId:member.deviceId})">交给此设备主持</button></footer>
              </article>
            </section>
            <details class="lab-help"><summary>如何让声音更齐？</summary><p>先选择右侧的“校准节拍”，等设备就绪后同步播放。逐台调整延迟补偿，直到重音重合：负值提前，正值延后。蓝牙音响需要单独校准。</p><p>“对时估计”和“调度偏差”反映软件时钟与播放调度，实际听到的声音还受到声卡、蓝牙与距离影响。</p></details>
          </template>
        </section>
        <aside class="lab-card lab-library">
          <header class="lab-card-heading"><div><p class="lab-eyebrow">SHARED SOURCE</p><h2>同一份声音</h2></div><span aria-hidden="true"><AppIcon name="arrow-up-right" :size="16" /></span></header>
          <p class="lab-muted">所有设备下载同一份音频，避免音质、版本或试听时长不一致。</p>
          <div class="lab-source-buttons">
            <button class="lab-secondary" :disabled="Boolean(state.groupBusy)" @click="importCurrent()">{{ state.groupBusy==='import'?'正在导入…':'使用播放器当前歌曲' }}</button>
            <label class="lab-file" :class="{'is-disabled':Boolean(state.groupBusy)}">选择本地音频<input type="file" accept="audio/*,.flac,.wav,.mp3,.m4a,.ogg" :disabled="Boolean(state.groupBusy)" @change="uploadSource($event.target.files[0]);$event.target.value=''" /></label>
            <button class="lab-quiet" :disabled="Boolean(state.groupBusy)" @click="calibration()">生成校准节拍</button>
          </div>
          <p class="lab-footnote">同步音源会临时上传，仅同账号设备可读取。最大32MB、10分钟；两小时未使用后清理。</p>
          <ul class="lab-sources"><li v-for="source in state.sources" :key="source.id" :class="{'is-current':source.id===state.room?.source?.id}"><div><strong>{{ source.name }}</strong><small>{{ time(source.durationMs/1000) }} · {{ (source.bytes/1048576).toFixed(1) }} MiB</small></div><button class="lab-link" :disabled="!isHost || Boolean(state.groupBusy) || source.id===state.room?.source?.id" @click="selectSource(source.id)">{{ source.id===state.room?.source?.id?'使用中':'选择' }}</button><button class="lab-source-remove" aria-label="删除临时音源" :disabled="Boolean(state.groupBusy) || source.id===state.room?.source?.id" @click="removeSource(source.id)"><AppIcon name="x" :size="16" /></button></li></ul>
          <p v-if="!state.sources.length" class="lab-footnote">还没有临时音源。从当前歌曲或本地文件开始。</p>
        </aside>
      </div>
    </MaintenanceFeature>

    <MaintenanceFeature v-else target="feature.spatialMixer">
      <div class="lab-spatial">
        <aside class="lab-card lab-spatial-source">
          <header class="lab-card-heading"><div><p class="lab-eyebrow">ON YOUR DEVICE</p><h2>拆开一首歌</h2></div><span aria-hidden="true">✳</span></header>
          <p class="lab-muted">将人声、鼓、贝斯和其他乐器分开，再摆到你想听见的位置。</p>
          <label class="lab-file lab-file-large"><AppIcon name="plus" :size="16" /> 选择歌曲<input type="file" accept="audio/*,.wav,.mp3,.flac,.m4a" @change="setSpatialInput($event.target.files[0]);$event.target.value=''" /><small>本地文件在本机处理</small></label>
          <button v-if="user.isLoggedIn" class="lab-quiet lab-wide" :disabled="state.space.busy || Boolean(state.groupBusy)" @click="importCurrent()">从播放器当前歌曲导入</button>
          <p v-if="state.space.name" class="lab-file-name">{{ state.space.name }}</p>
          <template v-if="state.space.inputDuration">
            <div class="lab-range"><label><span>处理范围</span><select v-model="state.space.range" :disabled="state.space.busy"><option value="clip">先试一段</option><option value="full">整首歌曲</option></select></label><template v-if="state.space.range==='clip'"><label><span>起点 / 秒</span><input v-model.number="state.space.start" type="number" min="0" :max="Math.max(0,state.space.inputDuration-.1)" :disabled="state.space.busy"/></label><label><span>片段长度</span><select v-model.number="state.space.clipSeconds" :disabled="state.space.busy"><option :value="15">15秒</option><option :value="30">30秒</option><option :value="60">60秒</option></select></label></template></div>
            <button class="lab-primary lab-wide" :disabled="state.space.busy" @click="separate()">在本机分离声部</button>
          </template>
          <div v-if="state.space.busy || state.space.progress" class="lab-processing" role="status"><strong>{{ progressText }}</strong><progress v-if="state.space.progress?.percent!==null && state.space.progress?.percent!==undefined" :value="state.space.progress.percent" max="100" /><progress v-else /><small v-if="state.space.progress?.stage==='downloading'">{{ (state.space.progress.bytes/1048576).toFixed(1) }} / 172.2 MiB</small><button v-if="state.space.busy" class="lab-link" @click="cancelSeparation()">取消处理</button></div>
          <p class="lab-footnote">首次启用需下载约172MiB模型，之后使用本机缓存。处理耗时取决于设备算力，最长支持5分钟音频；建议先试一小段。</p>
          <p v-if="user.isLoggedIn" class="lab-footnote">从播放器导入歌曲时，会通过服务器临时获取音源。</p>
          <p v-if="state.space.error" class="lab-error" role="alert">{{ state.space.error }}</p>
          <details class="lab-stem-import"><summary>已有四个声部？直接导入</summary><p class="lab-footnote">选择同一作品、同一起点且时长一致的声部文件。</p><label v-for="stem in STEMS" :key="stem.id" class="lab-stem-file"><span :style="{color:stem.color}">●</span><strong>{{ stem.name }}</strong><small>{{ state.space.files[stem.id] || '选择文件' }}</small><input type="file" accept="audio/*,.wav,.mp3,.flac" @change="importStem(stem.id,$event.target.files[0]);$event.target.value=''" /></label></details>
          <button class="lab-link lab-cache-clear" @click="clearCache">清除本机模型缓存</button>
        </aside>
        <section class="lab-card lab-stage-card">
          <header class="lab-card-heading"><div><p class="lab-eyebrow">PLACE THE SOUND</p><h2>你的听音位置</h2></div><span class="lab-headphone"><AppIcon name="headphones" :size="14" /> 建议佩戴耳机</span></header>
          <p class="lab-muted">拖动四个声部，改变前后、左右和距离；选中后也可用方向键调整。</p>
          <div ref="stage" class="lab-stage" aria-label="声部空间布局" @pointermove="move" @pointerup="end" @pointercancel="end">
            <div class="lab-stage-ring ring-one"/><div class="lab-stage-ring ring-two"/><div class="lab-stage-ring ring-three"/><span class="lab-stage-front">前方</span><span class="lab-stage-back">后方</span><span class="lab-stage-left">左</span><span class="lab-stage-right">右</span>
            <div class="lab-listener" aria-label="听音者位于中央，面向前方"><AppIcon name="headphones" aria-hidden="true" /><small>你</small></div>
            <button v-for="stem in state.space.settings" :key="stem.id" class="lab-sound-node" :class="{'is-selected':selected===stem.id,'is-muted':stem.mute}" :style="{left:((stem.x+3)/6*100)+'%',top:((stem.z+3)/6*100)+'%','--stem-color':stem.color}" :aria-label="stem.name+'，左右位置'+stem.x.toFixed(1)+'，前后位置'+stem.z.toFixed(1)" @pointerdown="begin($event,stem.id)" @keydown="keyboard($event,stem)" @click="selected=stem.id"><span><AppIcon :name="stem.id==='vocals'?'mic':stem.id==='drums'?'drum':stem.id==='bass'?'audio-lines':'sparkles'" :size="20" /></span><strong>{{ stem.name }}</strong></button>
          </div>
          <div class="lab-spatial-controls"><button class="lab-primary" :disabled="!state.space.ready || state.space.busy" @click="toggleSpatial()">{{ state.space.playing?'暂停混音':'播放混音' }}</button><span>{{ time(state.space.position) }} / {{ time(state.space.duration) }}</span><label><span>混音音量</span><input type="range" min="0" max="1" step=".01" :value="state.space.volume" @input="spatialVolume(Number($event.target.value))"/></label></div>
          <input class="lab-spatial-seek" aria-label="混音进度" type="range" min="0" :max="state.space.duration||1" step=".01" :value="state.space.position" :disabled="!state.space.ready" @change="seekSpatial(Number($event.target.value))"/>
          <p v-if="!state.space.ready" class="lab-stage-empty">导入歌曲并完成分离，或直接导入四个声部，即可播放。</p>
          <div class="lab-stem-strips"><article v-for="stem in state.space.settings" :key="stem.id" :class="{'is-selected':selected===stem.id}" @click="selected=stem.id"><header><span :style="{background:stem.color}"/><strong>{{ stem.name }}</strong><small>{{ Math.round(stem.volume*100) }}%</small></header><input type="range" min="0" max="1.5" step=".01" :aria-label="stem.name+'音量'" :value="stem.volume" @input="updateStem(stem.id,{volume:Number($event.target.value)})"/><div><button :aria-pressed="stem.mute" :class="{'is-active':stem.mute}" @click.stop="updateStem(stem.id,{mute:!stem.mute})">静音</button><button :aria-pressed="stem.solo" :class="{'is-active':stem.solo}" @click.stop="updateStem(stem.id,{solo:!stem.solo})">独听</button><button :disabled="!state.space.ready" @click.stop="downloadStem(stem.id)" :aria-label="'导出'+stem.name+'声部'"><AppIcon name="arrow-down" :size="16" /></button></div></article></div>
          <footer class="lab-stage-footer"><label><span>{{ selectedStem.name }}高度</span><input type="range" min="-2" max="2" step=".1" :value="selectedStem.y" @input="updateStem(selected,{y:Number($event.target.value)})"/></label><small>布局自动保存在此设备</small><button class="lab-link" @click="resetLayout()">重置布局</button></footer>
        </section>
      </div>
    </MaintenanceFeature>
  </main>
</template>

<script setup>
import AppIcon from "@/components/icons/AppIcon.vue"
import {computed,ref} from 'vue'
import {useRouter} from 'vue-router'
import AppHeader from '@/components/appHeader/AppHeader.vue'
import MaintenanceFeature from '@/components/maintenance/MaintenanceFeature.vue'
import {openLoginDialog} from '@/utils/loginDialog.js'
import {STEMS,studioPosition} from '@/utils/studioProtocol.js'
import {useAudioStudio} from '@/composables/useAudioStudio.js'
defineOptions({name:'AudioStudioPage'})
const router=useRouter(),studio=useAudioStudio()
const {user,state,api,ownMember,isHost,joined,createRoom,joinRoom,leaveRoom,command,selectSource,uploadSource,importCurrent,calibration,removeSource,previewOutput,saveOutput,setTab,setSpatialInput,separate,cancelSeparation,importStem,updateStem,resetLayout,toggleSpatial,seekSpatial,spatialVolume,downloadStem,reconnect,retrySource}=studio
const stage=ref(),selected=ref('vocals')
let dragging=null
const time=seconds=>{const s=Math.max(0,Math.floor(Number(seconds)||0));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
const groupPosition=computed(()=>studioPosition(state.room,state.now||0))
const countdown=computed(()=>state.room?.playing?Math.max(0,Math.ceil((state.room.startsAt-(state.now||state.room.serverTime))/1000)):0)
const selectedStem=computed(()=>state.space.settings.find(s=>s.id===selected.value)||state.space.settings[0])
const progressText=computed(()=>{
  const p=state.space.progress
  if(!p)return '正在读取音频'
  return ({checking:'检查本机模型缓存',cached:'已找到本机模型',downloading:'下载本地分离模型',loading:'初始化本机分离引擎',done:'四声部已准备好'})[p.stage]||(p.stage==='separating'?'已处理 '+p.completed+' / '+p.total+' 段音频':'正在处理音频')
})
function canAdjust(member){return joined.value&&(isHost.value||member.deviceId===api.deviceId)}
function begin(event,id){selected.value=id;dragging={id,pointerId:event.pointerId};event.currentTarget.setPointerCapture(event.pointerId);event.preventDefault()}
function move(event){
  if(!dragging||dragging.pointerId!==event.pointerId)return
  const rect=stage.value.getBoundingClientRect()
  const x=Math.max(-2.8,Math.min(2.8,(event.clientX-rect.left)/rect.width*6-3))
  const z=Math.max(-2.8,Math.min(2.8,(event.clientY-rect.top)/rect.height*6-3))
  updateStem(dragging.id,{x:Math.round(x*10)/10,z:Math.round(z*10)/10})
}
function end(){dragging=null}
function keyboard(event,stem){
  const changes={ArrowLeft:{x:Math.max(-2.8,stem.x-.1)},ArrowRight:{x:Math.min(2.8,stem.x+.1)},ArrowUp:{z:Math.max(-2.8,stem.z-.1)},ArrowDown:{z:Math.min(2.8,stem.z+.1)}}
  if(changes[event.key]){event.preventDefault();updateStem(stem.id,changes[event.key])}
}
async function clearCache(){try{await studio.clearStudioModelCache();state.notice='本机模型缓存已清除，下次分离时会重新下载'}catch{state.space.error='暂时无法清除缓存，请稍后重试'}}
</script>

<style scoped>
.audio-lab{--lab-ink:#263c3b;--lab-muted:#748581;--lab-line:#e0e8e4;--lab-accent:#427c70;max-width:1520px;margin:0 auto;padding:42px 34px 150px;color:var(--lab-ink)}
.lab-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:30px}.lab-eyebrow{font-size:10px;font-weight:800;letter-spacing:2px;color:#859c94;margin:0 0 10px}.lab-heading h1{font-size:clamp(27px,3vw,42px);font-weight:800;letter-spacing:-1.4px;margin:0 0 12px}.lab-heading>div>p:last-child{font-size:13px;color:var(--lab-muted);margin:0}
button,input,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.4;cursor:not-allowed}.lab-quiet,.lab-primary,.lab-secondary,.lab-file{border-radius:12px;padding:11px 16px;font-size:12px;font-weight:650;transition:background .2s,border-color .2s;display:inline-flex;align-items:center;justify-content:center;gap:8px}.lab-quiet{background:transparent;border:1px solid var(--lab-line);color:var(--lab-ink)}.lab-primary{background:var(--lab-accent);border:1px solid var(--lab-accent);color:white}.lab-primary:hover:not(:disabled){background:#326457}.lab-secondary{background:#edf4ef;border:1px solid #d9e5dd;color:var(--lab-accent)}.lab-link{font-size:11px;color:var(--lab-accent);border:0;background:none;padding:4px 0;white-space:nowrap}.lab-wide{width:100%}.lab-muted{font-size:12px;line-height:1.8;color:var(--lab-muted);margin:10px 0}.lab-footnote{font-size:11px;color:var(--lab-muted);line-height:1.8;margin:15px 0}
